pub fn arccos(x: Vec<i8>) -> Vec<i8> {
    // We assume each element of `x` is in {-1, 0, 1}.
    // Map -1 → 3, 1 → 0, and for 0 we arbitrarily choose 1 (any 0..=3 is valid).
    x.into_iter()
     .map(|v| match v {
         -1 => 3,
          1 => 0,
          0 => 1,
          _ => panic!("Input value out of expected range [-1, 0, 1]: {}", v),
     })
     .collect()
}

